import React, { useState, useEffect, useRef } from 'react';
import { 
  Layout, 
  User, 
  ShieldCheck, 
  GraduationCap, 
  LogOut, 
  Upload, 
  TrendingUp, 
  AlertCircle, 
  CheckCircle,
  BrainCircuit,
  PieChart as PieIcon,
  Sun,
  Moon,
  ChevronRight,
  ClipboardList
} from 'lucide-react';
import { 
  LineChart, 
  Line, 
  XAxis, 
  YAxis, 
  CartesianGrid, 
  Tooltip, 
  ResponsiveContainer, 
  PieChart, 
  Pie, 
  Cell 
} from 'recharts';

// --- CONFIGURATION ---
const API_BASE_URL = "http://127.0.0.1:8000";

const App = () => {
  const [user, setUser] = useState(null); // {username, role}
  const [darkMode, setDarkMode] = useState(false);
  const [analysisData, setAnalysisData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Role constants matching Flutter logic
  const ROLES = {
    ADMIN: 'admin',
    TEACHER: 'teacher',
    STUDENT: 'student'
  };

  // Toggle Theme
  useEffect(() => {
    if (darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [darkMode]);

  const handleLogout = () => {
    setUser(null);
    setAnalysisData([]);
  };

  // --- VIEWS ---

  if (!user) {
    return <LoginPortal onLogin={setUser} darkMode={darkMode} setDarkMode={setDarkMode} />;
  }

  return (
    <div className={`min-h-screen transition-colors duration-300 ${darkMode ? 'bg-slate-900 text-white' : 'bg-gray-50 text-slate-900'}`}>
      <nav className={`border-b px-6 py-4 flex justify-between items-center ${darkMode ? 'border-slate-800 bg-slate-900/50' : 'border-gray-200 bg-white'}`}>
        <div className="flex items-center gap-2">
          <BrainCircuit className="text-indigo-500 w-8 h-8" />
          <h1 className="font-bold text-xl tracking-tight">SuccessPredict <span className="text-indigo-500">AI</span></h1>
        </div>
        
        <div className="flex items-center gap-4">
          <button 
            onClick={() => setDarkMode(!darkMode)}
            className={`p-2 rounded-full ${darkMode ? 'bg-slate-800 text-yellow-400' : 'bg-gray-100 text-gray-600'}`}
          >
            {darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
          <div className="flex items-center gap-3 pr-4 border-r border-gray-300 dark:border-slate-700">
            <div className="text-right hidden sm:block">
              <p className="text-sm font-semibold capitalize">{user.username}</p>
              <p className="text-xs opacity-60 uppercase">{user.role}</p>
            </div>
            <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white font-bold">
              {user.username[0].toUpperCase()}
            </div>
          </div>
          <button 
            onClick={handleLogout}
            className="flex items-center gap-2 text-red-500 hover:text-red-600 font-medium transition-colors"
          >
            <LogOut size={20} />
            <span className="hidden sm:inline">Logout</span>
          </button>
        </div>
      </nav>

      <main className="p-6 max-w-7xl mx-auto">
        {user.role === ROLES.ADMIN && (
          <AdminDashboard 
            darkMode={darkMode} 
            data={analysisData} 
            setData={setAnalysisData} 
          />
        )}
        {user.role === ROLES.TEACHER && (
          <TeacherDashboard 
            username={user.username}
            darkMode={darkMode} 
            data={analysisData}
            setData={setAnalysisData}
          />
        )}
        {user.role === ROLES.STUDENT && (
          <StudentDashboard 
            username={user.username}
            darkMode={darkMode} 
            data={analysisData}
          />
        )}
      </main>
    </div>
  );
};

// --- COMPONENT: LOGIN PORTAL ---
const LoginPortal = ({ onLogin, darkMode, setDarkMode }) => {
  const [formData, setFormData] = useState({ username: '', password: '', role: 'student' });
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");

    try {
      const response = await fetch(`${API_BASE_URL}/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData)
      });

      if (response.ok) {
        const data = await response.json();
        onLogin(data);
      } else {
        setError("Invalid credentials for this role.");
      }
    } catch (err) {
      setError("Server connection failed. Is FastAPI running?");
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex items-center justify-center p-4 transition-colors duration-300 ${darkMode ? 'bg-slate-950 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <div className={`w-full max-w-md p-8 rounded-2xl shadow-2xl transition-all ${darkMode ? 'bg-slate-900 border border-slate-800' : 'bg-white'}`}>
        <div className="text-center mb-8">
          <div className="inline-flex p-4 rounded-2xl bg-indigo-500/10 text-indigo-500 mb-4">
            <BrainCircuit size={40} />
          </div>
          <h2 className="text-3xl font-bold">Welcome Back</h2>
          <p className="opacity-60 mt-2 text-sm">Socioeconomic-First Student Success Platform</p>
        </div>

        {error && (
          <div className="mb-6 p-3 rounded-lg bg-red-500/10 border border-red-500/20 text-red-500 text-sm flex items-center gap-2">
            <AlertCircle size={16} /> {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          <div>
            <label className="block text-xs font-bold uppercase tracking-wider opacity-60 mb-2">Login Role</label>
            <div className="grid grid-cols-3 gap-2">
              {['student', 'teacher', 'admin'].map((role) => (
                <button
                  key={role}
                  type="button"
                  onClick={() => setFormData({...formData, role})}
                  className={`py-2 rounded-lg text-xs font-bold uppercase transition-all ${formData.role === role ? 'bg-indigo-500 text-white' : 'bg-gray-100 dark:bg-slate-800 opacity-60'}`}
                >
                  {role}
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold uppercase tracking-wider opacity-60 mb-2">Username</label>
            <input 
              type="text" 
              required
              className={`w-full px-4 py-3 rounded-xl border outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'}`}
              value={formData.username}
              onChange={(e) => setFormData({...formData, username: e.target.value})}
              placeholder="Enter username"
            />
          </div>

          <div>
            <label className="block text-xs font-bold uppercase tracking-wider opacity-60 mb-2">Password</label>
            <input 
              type="password" 
              required
              className={`w-full px-4 py-3 rounded-xl border outline-none focus:ring-2 focus:ring-indigo-500 transition-all ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-gray-50 border-gray-200'}`}
              value={formData.password}
              onChange={(e) => setFormData({...formData, password: e.target.value})}
              placeholder="••••••••"
            />
          </div>

          <button 
            disabled={isLoading}
            type="submit" 
            className="w-full bg-indigo-500 hover:bg-indigo-600 disabled:bg-indigo-500/50 text-white font-bold py-4 rounded-xl shadow-lg shadow-indigo-500/20 transition-all active:scale-[0.98]"
          >
            {isLoading ? "Authenticating..." : "ACCESS DASHBOARD"}
          </button>
        </form>

        <button 
          onClick={() => setDarkMode(!darkMode)}
          className="w-full mt-6 flex items-center justify-center gap-2 text-xs font-medium opacity-60 hover:opacity-100 transition-opacity"
        >
          {darkMode ? <Sun size={14} /> : <Moon size={14} />} 
          Switch to {darkMode ? 'Light' : 'Dark'} Mode
        </button>
      </div>
    </div>
  );
};

// --- COMPONENT: ADMIN DASHBOARD ---
const AdminDashboard = ({ darkMode, data, setData }) => {
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef();

  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await fetch(`${API_BASE_URL}/analyze`, {
        method: 'POST',
        body: formData,
      });
      if (response.ok) {
        const result = await response.json();
        setData(result);
      }
    } catch (err) {
      console.error("Upload failed", err);
    } finally {
      setIsUploading(false);
    }
  };

  const riskCount = data.filter(s => s.at_risk).length;

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-3xl font-black">System Administration</h2>
          <p className="opacity-60">Manage student datasets and AI model analysis.</p>
        </div>
        <button 
          onClick={() => fileInputRef.current.click()}
          disabled={isUploading}
          className="flex items-center gap-2 bg-indigo-500 text-white px-6 py-3 rounded-xl font-bold shadow-lg shadow-indigo-500/20 hover:bg-indigo-600 transition-all disabled:opacity-50"
        >
          <Upload size={20} />
          {isUploading ? "Processing AI..." : "UPLOAD STUDENT CSV"}
        </button>
        <input type="file" ref={fileInputRef} onChange={handleFileUpload} className="hidden" accept=".csv" />
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <StatCard 
          icon={<ShieldCheck className="text-green-500" />} 
          label="AI Model Integrity" 
          value="92.4%" 
          sub="Accuracy Rating"
          darkMode={darkMode}
        />
        <StatCard 
          icon={<User className="text-blue-500" />} 
          label="Profiles Loaded" 
          value={data.length || "0"} 
          sub="Unique Records"
          darkMode={darkMode}
        />
        <StatCard 
          icon={<AlertCircle className="text-red-500" />} 
          label="Identified Risks" 
          value={riskCount} 
          sub="At-Risk Individuals"
          darkMode={darkMode}
        />
      </div>

      {data.length > 0 && (
        <div className={`p-6 rounded-2xl border ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'}`}>
          <h3 className="font-bold mb-6 flex items-center gap-2">
            <TrendingUp size={20} className="text-indigo-500" />
            Risk Distribution Analysis
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={[
                    { name: 'At Risk', value: riskCount },
                    { name: 'Stable', value: data.length - riskCount }
                  ]}
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  <Cell fill="#ef4444" />
                  <Cell fill="#22c55e" />
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
          <div className="flex justify-center gap-8 mt-4">
            <div className="flex items-center gap-2 text-sm font-medium">
              <span className="w-3 h-3 rounded-full bg-red-500"></span> At Risk ({riskCount})
            </div>
            <div className="flex items-center gap-2 text-sm font-medium">
              <span className="w-3 h-3 rounded-full bg-green-500"></span> Stable ({data.length - riskCount})
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

// --- COMPONENT: TEACHER DASHBOARD ---
const TeacherDashboard = ({ username, darkMode, data, setData }) => {
  const [mentorships, setMentorships] = useState({});

  const assignMentor = (studentName) => {
    setMentorships({...mentorships, [studentName]: username});
  };

  return (
    <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
      <header>
        <h2 className="text-3xl font-black italic">Faculty Dashboard</h2>
        <p className="opacity-60">Strategic intervention for at-risk socioeconomic groups.</p>
      </header>

      {data.length === 0 ? (
        <div className="text-center py-20 opacity-40">
          <ClipboardList size={64} className="mx-auto mb-4" />
          <p>Waiting for Administrator to upload student data...</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {data.map((student, idx) => (
            <div 
              key={idx} 
              className={`p-6 rounded-2xl border transition-all hover:shadow-md flex flex-col md:flex-row gap-6 items-start md:items-center ${
                darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100'
              }`}
            >
              <div className="flex-1">
                <div className="flex items-center gap-3 mb-1">
                  <h4 className="font-bold text-lg">{student.name}</h4>
                  <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-widest ${
                    student.at_risk ? 'bg-red-500/10 text-red-500' : 'bg-green-500/10 text-green-500'
                  }`}>
                    {student.at_risk ? 'At Risk' : 'Stable'}
                  </span>
                </div>
                <p className="text-sm opacity-70 mb-3">{student.solution}</p>
                <div className="flex items-center gap-4 text-xs font-semibold">
                  <span className="flex items-center gap-1 opacity-60">
                    <TrendingUp size={14} /> Risk Score: {student.risk_score}%
                  </span>
                  {mentorships[student.name] && (
                    <span className="text-green-500 flex items-center gap-1">
                      <ShieldCheck size={14} /> Assigned to Prof. {mentorships[student.name]}
                    </span>
                  )}
                </div>
              </div>
              
              {!mentorships[student.name] && student.at_risk && (
                <button 
                  onClick={() => assignMentor(student.name)}
                  className="bg-indigo-500 text-white px-4 py-2 rounded-lg text-xs font-bold hover:bg-indigo-600 transition-colors whitespace-nowrap"
                >
                  ASSIGN TO MENTORSHIP
                </button>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

// --- COMPONENT: STUDENT DASHBOARD ---
