        <div className="w-24 h-24 bg-indigo-500 rounded-full flex items-center justify-center text-white text-3xl font-black mx-auto mb-6 shadow-lg shadow-indigo-500/30">
          {username[0].toUpperCase()}
        </div>
        <h2 className="text-3xl font-bold mb-1">{username}</h2>
        <p className="text-sm opacity-60 mb-8 tracking-widest uppercase font-bold">Student Success Profile</p>

        <div className="grid grid-cols-2 gap-4 mb-10">
          <div className={`p-4 rounded-2xl ${darkMode ? 'bg-slate-900/50' : 'bg-gray-50'}`}>
