          </div>
          <div className={`p-4 rounded-2xl ${darkMode ? 'bg-slate-900/50' : 'bg-gray-50'}`}>
            <p className="text-[10px] font-bold opacity-40 uppercase tracking-widest mb-1">Security Score</p>
            <p className="font-bold text-indigo-500">{(100 - myData.risk_score).toFixed(1)}%</p>
          </div>
