          <div className={`p-6 rounded-2xl border-l-4 border-l-indigo-500 leading-relaxed ${darkMode ? 'bg-indigo-500/5 text-indigo-100' : 'bg-indigo-50'}`}>
            {myData.solution}
          </div>
        </div>
      </div>
    </div>
  );
};

// --- HELPER COMPONENT: STAT CARD ---
const StatCard = ({ icon, label, value, sub, darkMode }) => (
  <div className={`p-6 rounded-2xl border transition-all ${darkMode ? 'bg-slate-800 border-slate-700' : 'bg-white border-gray-100 shadow-sm'}`}>
    <div className="flex items-center gap-3 mb-4">
      <div className="p-2 rounded-lg bg-gray-500/5">{icon}</div>
      <span className="text-xs font-bold uppercase tracking-widest opacity-40">{label}</span>
    </div>
    <div className="flex items-baseline gap-2">
      <h3 className="text-3xl font-black tracking-tight">{value}</h3>
      <span className="text-xs opacity-50 font-medium">{sub}</span>
    </div>
  </div>
);

export default App;
